// Checks the demo profile seed (db/019_demo_profile.sql, generated by scripts/demo-profile.ts): the file matches the
// script, only invented example.com links, no fixed dates, and the sections agree with each other, using the app's
// own maths (pipeline history, Today against Engagement, warm paths, the Digest, AI citations trend, Profile Studio).
// The rows are evaluated on several days of the week, as the seed's dates are relative. Run: node scripts/test-demo.ts
// Weeks are counted in UTC here, the database's day. In a browser far from UTC the week can turn a few hours early or late.
process.env.TZ = "UTC";
import { readFileSync } from "node:fs";
import { buildDemo, evaluate, warmCount, SQL_PATH, WS, STAGES, QUOTAS, PERSON, COMPANY, TOPICS, ENGINES_USED, PERSON_NAMED, COMPANY_NAMED, REF_NOW } from "./demo-profile.ts";
import { subjectShare, personContext, runsInWeek, weekStartOf, detectPerson, type Run, type Question, type Entity } from "../src/lib/citations.ts";
import { parseProfile, auditProfile } from "../src/lib/profile.ts";
import { buildTopics, selectDigest, bandOf, DEFAULT_WEIGHTS, DEFAULT_BANDS, type Finding } from "../src/lib/discovery.ts";
import { normCompany } from "../src/lib/network.ts";

let fails = 0;
const ok = (name: string, cond: boolean, detail = "") => { if (!cond) fails++; console.log(`${cond ? "ok  " : "FAIL"} ${name}${cond || !detail ? "" : `: ${detail}`}`); };
type R = Record<string, any>;

const demo = buildDemo();
const sql = readFileSync(SQL_PATH, "utf8");

// ---------- the file ----------
ok("db/019 matches the generator (run node scripts/demo-profile.ts after a change)", sql === demo.sql);
ok("one transaction", /^begin;$/m.test(sql) && /^commit;$/m.test(sql));
ok("comment trigger paused and restored", sql.includes("disable trigger comment_logged") && sql.indexOf("enable trigger comment_logged") > sql.indexOf("disable trigger comment_logged"));
ok("adds is_demo if missing", sql.includes("add column if not exists is_demo boolean"));
ok("owner email set at the top", /set_config\('prax\.demo_owner_email', 'owner@example\.com', false\);\s+-- OWNER EMAIL/.test(sql));
ok("falls back to auth.uid()", sql.includes("coalesce(u, auth.uid())"));
ok("re-runnable: deletes the previous demo copy first", sql.indexOf(`delete from workspaces where id = '${WS}'`) < sql.indexOf("insert into workspaces"));
ok("the earlier delete only touches demo rows by slug", sql.includes("slug = 'demo-layla-haddad' and is_demo"));
const tail = sql.slice(sql.indexOf("remove the demo profile"));
ok("commented delete block at the bottom", tail.includes(`-- delete from workspaces where id = '${WS}' and is_demo;`) && !/^delete/m.test(tail));
ok("no fixed calendar dates in the rows", !/'\d{4}-\d{2}-\d{2}/.test(sql.slice(sql.indexOf("insert into"))));
const hosts = [...sql.matchAll(/https?:\/\/([a-z0-9.-]+)/gi)].map((m) => m[1].toLowerCase());
const bad = [...new Set(hosts.filter((h) => !h.endsWith("example.com")))];
ok("every link is an example.com host", bad.length === 0, bad.join(", "));
const emails = [...new Set([...sql.matchAll(/[\w.+-]+@([\w-]+\.[\w.]+)/g)].map((m) => m[1]))];
ok("every email is an example.com address", emails.every((e) => e.endsWith("example.com")), emails.join(", "));
ok("no real profile names", !/shashi|antier|alok/i.test(sql.replace(/channel, |'shashi'/g, "")));
ok("every row targets the demo workspace", demo.tables.every((t) => t.rows.every((r) => (r.workspace_id ?? r.id) === WS)));

// ---------- consistency, evaluated on several days ----------
const DAYS = ["2026-11-02T10:00:00Z", "2026-11-04T15:00:00Z", "2026-11-06T09:00:00Z", "2026-11-08T20:00:00Z", "2027-03-15T12:00:00Z"].map((s) => new Date(s));
const ymd = (d: Date) => d.toISOString().slice(0, 10);
const plus = (s: string, n: number) => { const d = new Date(s + "T12:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return ymd(d); };
const isoDow = (s: string) => ((new Date(s.slice(0, 10) + "T12:00:00Z").getUTCDay() + 6) % 7) + 1;

for (const now of DAYS) {
  const tag = `[${ymd(now)}]`;
  const t = ymd(now);
  const tb: Record<string, R[]> = Object.fromEntries(demo.tables.map((x) => [x.name, evaluate(x.rows, now)]));
  // The two deletes at the end of the SQL.
  tb.daily_items = tb.daily_items.filter((r) => !(r.kind === "inmail" && isoDow(r.day) > 5));
  tb.activity = tb.activity.filter((r) => !(r.kind === "inmail" && isoDow(r.at) > 5));
  const nowIso = now.toISOString();
  const allTimes = demo.tables.flatMap((x) => evaluate(x.rows, now).flatMap((r) => Object.entries(r).filter(([k, v]) => typeof v === "string" && /(_at|^at|run_at|found_at)$/.test(k) && /T\d\d:/.test(v)).map(([, v]) => v as string)));
  ok(`${tag} nothing happens in the future`, allTimes.every((v) => v <= nowIso), allTimes.filter((v) => v > nowIso).slice(0, 3).join(", "));

  // Pipeline
  const P = tb.prospects, M = tb.stage_moves;
  const stages = new Set(P.map((p) => p.stage));
  ok(`${tag} about 40 prospects`, P.length >= 38 && P.length <= 42, String(P.length));
  ok(`${tag} every stage has someone`, STAGES.every((s) => stages.has(s)));
  const open = P.filter((p) => !["Won", "Parked"].includes(p.stage));
  ok(`${tag} every open lead has a next action and date`, open.every((p) => p.next_action && p.next_date));
  const overdue = open.filter((p) => p.next_date < t), dueToday = open.filter((p) => p.next_date === t);
  ok(`${tag} some follow-ups are overdue`, overdue.length >= 4, String(overdue.length));
  ok(`${tag} some are due today`, dueToday.length >= 1);
  ok(`${tag} Parked has a lost reason`, P.filter((p) => p.stage === "Parked").every((p) => p.lost_reason));
  for (const p of P) {
    const mine = M.filter((m) => m.prospect_id === p.id).sort((a, b) => (a.at < b.at ? -1 : 1));
    const chain = mine.every((m, i) => i === 0 ? m.from_stage === "Target" : m.from_stage === mine[i - 1].to_stage);
    const last = mine[mine.length - 1];
    if (!(chain && (last ? last.to_stage === p.stage && last.at === p.stage_changed_at : p.stage === "Target") && (!mine.length || p.created_at < mine[0].at))) {
      ok(`${tag} history of ${p.name} matches the stage`, false, JSON.stringify(mine.map((m) => [m.from_stage, m.to_stage, m.at])));
    }
  }
  ok(`${tag} stage history matches every lead (above if not)`, true);
  const stageActs = tb.activity.filter((a) => a.kind === "stage");
  ok(`${tag} one feed row per stage move`, stageActs.length === M.length);

  // Today and Engagement
  const I = tb.daily_items, C = tb.comment_log;
  const keys = I.map((r) => `${r.day}|${r.kind}|${r.idx}`);
  ok(`${tag} Today items are unique per day, kind and index`, new Set(keys).size === keys.length);
  const days = [...new Set(I.map((r) => r.day))].sort();
  ok(`${tag} Today covers the last 28 days including today`, days.length === 28 && days[27] === t && days[0] === plus(t, -27));
  ok(`${tag} quota items every day`, days.every((d) => (["comment", "request", "dm", "reply"] as const).every((k) => I.filter((r) => r.day === d && r.kind === k).length === QUOTAS[k])));
  ok(`${tag} InMail only on weekdays`, I.filter((r) => r.kind === "inmail").every((r) => isoDow(r.day) <= 5));
  const todays = I.filter((r) => r.day === t);
  ok(`${tag} today is partly done`, todays.some((r) => r.done) && todays.some((r) => !r.done));
  const doneComments = I.filter((r) => r.kind === "comment" && r.done);
  ok(`${tag} one logged comment per finished comment task, day by day`, days.every((d) => doneComments.filter((r) => r.day === d).length === C.filter((c) => c.day === d).length));
  ok(`${tag} comment tasks and the log name the same people`, doneComments.every((r) => C.some((c) => c.day === r.day && c.author === r.note && c.url === r.link)));
  ok(`${tag} comments have replies`, C.filter((c) => c.reply).length >= 10, String(C.filter((c) => c.reply).length));
  ok(`${tag} logged comments point at real prospects`, C.every((c) => !c.prospect_id || P.some((p) => p.id === c.prospect_id)));
  ok(`${tag} nobody still at Target has been commented on`, C.every((c) => !c.prospect_id || P.find((p) => p.id === c.prospect_id)!.stage !== "Target"));
  ok(`${tag} each warmed lead had a comment on the day it warmed`, M.filter((m) => m.to_stage === "Warming").every((m) => C.some((c) => c.prospect_id === m.prospect_id && c.day === m.at.slice(0, 10))));
  ok(`${tag} every finished task has a feed row`, I.filter((r) => r.done).every((r) => tb.activity.some((a) => a.ref_id === r.id)));
  ok(`${tag} drafting stats line up with the log`, tb.ext_usage.filter((u) => u.kind === "scores").length === C.length);

  // Content
  const posts = tb.posts;
  const posted = posts.filter((p) => p.status === "Posted");
  ok(`${tag} posted, planned and in review posts`, posted.length >= 6 && posts.some((p) => p.status === "In review") && posts.some((p) => ["Ready", "Drafting"].includes(p.status)) && posts.some((p) => p.status === "Idea"));
  ok(`${tag} posted ones are in the past with results`, posted.every((p) => p.publish_date < t && p.impressions > 0 && p.reactions > 0 && p.url));
  ok(`${tag} planned ones are in the future without results`, posts.filter((p) => ["In review", "Ready", "Drafting"].includes(p.status)).every((p) => p.publish_date > t && p.impressions == null));
  ok(`${tag} templates and strategy notes`, tb.templates.length >= 5 && tb.notes.filter((n) => n.kind === "strategy").length >= 3);

  // Network
  const N = tb.network_people;
  const warm = warmCount(P as any, N as any);
  ok(`${tag} warm paths for open leads`, warm >= 15 && warm <= open.length, String(warm));
  ok(`${tag} linked people are connected or invited`, N.filter((n) => n.prospect_id).every((n) => n.is_connection));
  ok(`${tag} linked people match their lead's company`, N.filter((n) => n.prospect_id).every((n) => normCompany(n.company) === normCompany(P.find((p) => p.id === n.prospect_id)!.company)));
  ok(`${tag} network keys are unique`, new Set(N.map((n) => n.key)).size === N.length);
  ok(`${tag} import counts match the people`, tb.network_imports[0].counts.connections === N.filter((n) => n.is_connection).length);

  // Discovery
  const F = tb.discovery_findings.map((f) => ({ ...f, scores: f.scores.map(Number) })) as unknown as Finding[];
  ok(`${tag} seven scores of 0 to 5 per finding`, F.every((f) => f.scores.length === 7 && f.scores.every((s) => s >= 0 && s <= 5)));
  ok(`${tag} every band appears`, ["Post-worthy", "Watch", "Dropped"].every((b) => F.some((f) => bandOf(f) === b)) && F.some((f) => bandOf(f) === "Comment-worthy"));
  ok(`${tag} older weeks have sent, watched and dismissed findings`, ["sent", "watched", "dismissed"].every((s) => F.some((f) => f.status === s)));
  const warmOf = (orgs: string[]) => orgs.reduce((a, o) => a + N.filter((p) => p.is_connection && normCompany(p.company) !== "" && normCompany(p.company) === normCompany(o)).length, 0);
  const digest = selectDigest(buildTopics(F, { weights: DEFAULT_WEIGHTS, bands: DEFAULT_BANDS, today: t, warm: warmOf, posts: posts as any }));
  const ten = [...digest.top, ...digest.list];
  const stored = tb.discovery_topics.sort((a, b) => a.rank - b.rank);
  ok(`${tag} the stored Digest matches what Discovery ranks`, JSON.stringify(stored.map((x) => [x.key, x.rank, x.score])) === JSON.stringify(ten.map((x, i) => [x.key, i + 1, x.score])), JSON.stringify(ten.map((x) => x.score)));
  ok(`${tag} at least three topics`, ten.length >= 3);
  ok(`${tag} topic week is this Monday`, stored.every((x) => x.week === weekStartOf(t + "T12:00:00")));
  const sentTopic = stored.find((x) => x.sent_at);
  ok(`${tag} the sent topic has its idea in Content Studio`, !!sentTopic && posts.some((p) => p.id === sentTopic.post_id && p.source_kind === "discovery" && p.status === "Idea"));
  const lastAi = tb.discovery_runs.filter((r) => r.kind === "ai").sort((a, b) => (a.started_at < b.started_at ? 1 : -1))[0];
  ok(`${tag} the latest AI search is recent (no surprise auto run)`, Date.parse(nowIso) - Date.parse(lastAi.started_at) < 3 * 3600e3);

  // AI citations
  const runs: Run[] = tb.citation_runs.map((r) => ({ ...r, sources: tb.citation_sources.filter((s) => s.run_id === r.id).sort((a, b) => a.sort - b.sort) })) as any;
  const qs = tb.citation_questions as unknown as Question[];
  const ents = tb.citation_entities as unknown as Entity[];
  const person = ents.find((e) => e.kind === "self" && e.subject === "person")!, company = ents.find((e) => e.kind === "self" && e.subject === "company")!;
  const ctx = personContext(qs, company);
  const weeks = [...new Set(runs.map((r) => weekStartOf(r.run_at)))].sort();
  ok(`${tag} four weekly batches`, weeks.length === 4 && runs.length === qs.length * ENGINES_USED.length * 4);
  const pShare = weeks.map((w) => subjectShare(runsInWeek(runs, w), qs, "person", person, company, ctx, ["expert", "leadership"]));
  const cShare = weeks.map((w) => subjectShare(runsInWeek(runs, w), qs, "company", company, company, ctx, ["vendor", "leadership"]));
  ok(`${tag} ${PERSON} named more each week`, JSON.stringify(pShare.map((s) => s.named)) === JSON.stringify(PERSON_NAMED), JSON.stringify(pShare.map((s) => s.named)));
  // Leadership answers that name her also name the company, so its count is at least the planned one.
  ok(`${tag} ${COMPANY} named more each week`, cShare.every((s, i) => s.named >= COMPANY_NAMED[i] && (i === 0 || s.named > cShare[i - 1].named)), JSON.stringify(cShare.map((s) => s.named)));
  ok(`${tag} named and not named answers both present this week`, pShare[3].named > 0 && pShare[3].named < pShare[3].total);
  ok(`${tag} no answer needs a person review`, runs.every((r) => !detectPerson(r, person, company, ctx).review));
  ok(`${tag} every answer has cited sources`, runs.every((r) => r.sources.filter((s) => s.cited).length >= 2));
  ok(`${tag} her own pages appear only where she or the company is named`, runs.every((r) => !r.sources.some((s) => s.domain.includes("northgate")) || r.answer.includes(COMPANY)));
  ok(`${tag} the latest batch is from today or yesterday`, Date.parse(nowIso) - Date.parse(runs.map((r) => r.run_at).sort().pop()!) < 3 * 3600e3);

  // Profile Studio
  const docs = tb.profile_docs.sort((a, b) => (a.created_at < b.created_at ? -1 : 1));
  const scores = docs.map((d) => auditProfile(parseProfile(d.raw_text), TOPICS).score);
  ok(`${tag} two or more reviews, each better than the last`, docs.length >= 2 && scores.every((s, i) => i === 0 || s > scores[i - 1]), scores.join(" < "));
  ok(`${tag} stored scores match the audit`, docs.every((d, i) => d.score === scores[i] && d.audit.score === scores[i]));
  ok(`${tag} the profile reads as ${PERSON}`, docs.every((d) => d.parsed.name === PERSON));

  // Dashboard numbers come from the same rows
  const reach = tb.snapshots.filter((s) => s.metric === "followers").sort((a, b) => (a.captured_at < b.captured_at ? -1 : 1)).map((s) => s.value);
  ok(`${tag} followers grow`, reach.every((v, i) => i === 0 || v > reach[i - 1]));
  ok(`${tag} the owner can see the AI citations profile`, tb.citation_profile_picks.length === 1 && tb.citation_profiles[0].id === tb.citation_profile_picks[0].profile_id);
}

const ws = demo.tables.find((t) => t.name === "workspaces")!.rows[0];
ok("workspace is marked as a demo", ws.is_demo === true);
ok("pillars, regions and segments filled in", (ws.pillars as string[]).length >= 4 && (ws.regions as string[]).length >= 1 && Object.keys((ws.segments as any).json).length === 5);
ok("digest computed at the reference date is the one stored", demo.digest.top.length > 0 && REF_NOW instanceof Date);

console.log(fails ? `\n${fails} failed` : "\nall passed");
process.exit(fails ? 1 : 0);
